#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t, a;
    cin >> t;

    while (t--) {
        cin >> a;
        bool possible = false;

        for (int sevens = 0; sevens <= a; sevens += 7) {
            if ((a - sevens) % 3 == 0) {
                possible = true;
                break;
            }
        }

        cout << (possible ? "YES" : "NO") << '\n';
    }

    return 0;
}

